// src/components/DecryptedText.js
import { useEffect, useState, useRef } from 'react';

const DecryptedText = ({ 
  text, 
  speed = 50, 
  animateOn = 'view',
  className = '',
  parentClassName = '',
  sequential = false,
  revealDirection = 'start',
  ...props 
}) => {
  const [displayText, setDisplayText] = useState(text);
  const [hasAnimated, setHasAnimated] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);
  const containerRef = useRef(null);

  useEffect(() => {
    if (animateOn === 'view' && !hasAnimated) {
      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              animateText();
              setHasAnimated(true);
            }
          });
        },
        { threshold: 0.3 }
      );

      if (containerRef.current) {
        observer.observe(containerRef.current);
      }

      return () => observer.disconnect();
    }
  }, [animateOn, hasAnimated]);

  const animateText = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
    let iteration = 0;
    setIsAnimating(true);

    const interval = setInterval(() => {
      setDisplayText(prevText => 
        text
          .split('')
          .map((char, index) => {
            if (char === ' ') return ' '; // Preserve spaces
            if (index < iteration) {
              return char; // Show correct character
            }
            return chars[Math.floor(Math.random() * chars.length)];
          })
          .join('')
      );

      if (iteration >= text.length) {
        clearInterval(interval);
        setDisplayText(text);
        setIsAnimating(false);
      }

      iteration += 1;
    }, speed);
  };

  return (
    <span 
      ref={containerRef} 
      className={`decrypted-text ${parentClassName} ${className}`}
      style={{
        fontFamily: 'monospace', // Use monospace to prevent width changes
        display: 'inline-block',
        minWidth: 'fit-content'
      }}
      {...props}
    >
      {displayText}
    </span>
  );
};

export default DecryptedText;
