import React, { useState } from 'react';
import { StackedCarousel, ResponsiveContainer } from 'react-stacked-center-carousel';
import './Certification.css';

// Dynamically import all images
const importAllImages = (requireContext) => {
  return requireContext.keys().map(requireContext);
};

const images = importAllImages(require.context('../certificates', false, /\.(png|jpe?g|gif)$/));

// Card component
const Card = React.memo(function (props) {
  const { data, dataIndex, swipeTo, slideIndex, isCenterSlide } = props;
  
  return (
    <div 
      className={`certificate-card-container ${isCenterSlide ? 'active-card' : ''}`}
      onClick={() => {
        if (!isCenterSlide) swipeTo(slideIndex);
      }}
    >
      <div className="certificate-card-inner">
        <img
          className="certificate-card-image"
          draggable={false}
          src={data[dataIndex]}
          alt={`Certificate ${dataIndex + 1}`}
        />
      </div>
    </div>
  );
});

const Certification = () => {
  const ref = React.useRef();
  const [autoPlay, setAutoPlay] = useState(true);
  
  // Pause autoplay on hover
  const handleMouseEnter = () => setAutoPlay(false);
  const handleMouseLeave = () => setAutoPlay(true);
  
  return (
    <div className="certification-container">
      <h1 className="HeadingCert">Certifications</h1>
      
      <div 
        className="carousel-wrapper"
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <ResponsiveContainer
          carouselRef={ref}
          render={(width, carouselRef) => (
            <StackedCarousel
              ref={carouselRef}
              slideComponent={Card}
              slideWidth={width < 800 ? width - 80 : 600}
              height={width < 800 ? 400 : 500}
              data={images}
              maxVisibleSlide={5}  // MUST be an odd number
              disableSwipe={false}
              transitionTime={450}
              autoPlay={autoPlay}
              autoPlayInterval={3000}
              customScales={[1, 0.85, 0.7, 0.55]}
              useGrabCursor={true}
            />
          )}
        />
        
        <div className="navigation-buttons">
          <button 
            onClick={() => ref.current?.goBack()} 
            className="nav-button prev-button"
          >
            ←
          </button>
          <button 
            onClick={() => ref.current?.goNext()} 
            className="nav-button next-button"
          >
            →
          </button>
        </div>
      </div>
    </div>
  );
};

export default Certification;
