// src/components/MediumBlog.js
import { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './MediumBlog.css';
import PixelCard from './PixelCard';

const useIsOverflow = (ref) => {
  const [isOverflow, setIsOverflow] = useState(false);
  useEffect(() => {
    const checkOverflow = () => {
      const el = ref.current;
      if (el) {
        setIsOverflow(el.scrollHeight > el.clientHeight);
      }
    };
    checkOverflow();
    window.addEventListener('resize', checkOverflow);
    return () => window.removeEventListener('resize', checkOverflow);
  }, [ref]);
  return isOverflow;
};

const MediumBlog = ({ username = 'amaterajat67' }) => {
  const [posts, setPosts] = useState([]);
  const [expanded, setExpanded] = useState(false);
  const [loading, setLoading] = useState(true);
  const containerRef = useRef(null);
  const hasOverflow = useIsOverflow(containerRef);

  useEffect(() => {
    const fetchPosts = async () => {
      try {
        const res = await axios.get(
          `https://api.rss2json.com/v1/api.json?rss_url=https://medium.com/feed/@${username}`
        );
        setPosts(res.data.items);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchPosts();
  }, [username]);

  if (loading) return <div className="mb-loading">Loading posts...</div>;
  if (!posts.length) return <div className="mb-error">No posts found.</div>;

  return (
    <section className="medium-blog">
      <h2 className="mb-title">My Medium Stories</h2>
      <div
        ref={containerRef}
        className={`posts-container ${expanded ? 'expanded' : ''}`}
      >
        <div className="posts-grid">
          {posts.map((post) => (
            <PixelCard key={post.guid} variant="blue" className="story-card">
              <div className="story-content">
                {post.thumbnail && (
                  <img
                    src={post.thumbnail}
                    alt={post.title}
                    className="story-image"
                  />
                )}
                <h1 className="story-title">{post.title}</h1>
                {/* <div
                  className="story-excerpt"
                  dangerouslySetInnerHTML={{ __html: post.description }}
                /> */}
                <div className="story-meta">
                  <span>{new Date(post.pubDate).toLocaleDateString()}</span>
                  {post.categories.length > 0 && (
                    <span>· {post.categories.join(', ')}</span>
                  )}
                </div>
                <button
                  className="story-button"
                  onClick={() => window.open(post.link, '_blank')}
                >
                  Read Article
                  <svg className="button-icon" viewBox="0 0 24 24">
                    <path d="M14 3v2h3.59l-9.83 9.83 1.41 1.41L19 6.41V10h2V3m-2 16H5V5h7V3H5c-1.11 0-2 .89-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7h-2v7z"/>
                  </svg>
                </button>
              </div>
            </PixelCard>
          ))}
        </div>
      </div>

      {hasOverflow && (
        <button
          className="expand-button"
          onClick={() => setExpanded(!expanded)}
        >
          {expanded ? 'Show Less' : 'Show More'}
          <span className={`arrow ${expanded ? 'up' : 'down'}`}></span>
        </button>
      )}

      <a
        href={`https://medium.com/@${username}`}
        target="_blank"
        rel="noopener noreferrer"
        className="medium-link-button"
      >
        View All on Medium
      </a>
    </section>
  );
};

export default MediumBlog;
