// src/components/Navbar1.js

import React, { useState, useEffect, useRef } from 'react';
import './Navbar.css';

const Navbar1 = () => {
  const [visible, setVisible] = useState(false);
  const [theme, setTheme] = useState('dark');
  const observerRef = useRef(null);

  useEffect(() => {
    // Show when mouse near top, hide when moves away
    const handleMouseMove = (e) => {
      if (e.clientY < 50) {
        setVisible(true);
      } else {
        setVisible(false);
      }
    };
    window.addEventListener('mousemove', handleMouseMove);

    // IntersectionObserver for theme
    observerRef.current = new IntersectionObserver(
      (entries) => {
        entries.forEach(({ target, isIntersecting }) => {
          if (isIntersecting && target.dataset.theme) {
            setTheme(target.dataset.theme);
          }
        });
      },
      { rootMargin: '-40% 0px -40% 0px' }
    );

    document.querySelectorAll('section[data-theme]').forEach((sec) =>
      observerRef.current.observe(sec)
    );

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      observerRef.current.disconnect();
    };
  }, []);

  return (
    <nav className={`navbar1 ${visible ? 'visible' : ''} theme-${theme}`}>
      <div className="navbar1__brand">Rajat Amate</div>
      <ul className="navbar1__links">
        <li><a href="#home">Home</a></li>
        <li><a href="#whyme">Why Me?</a></li>
        <li><a href="#projects">Projects</a></li>
        <li><a href="#mywork">My Works</a></li>
        <li><a href="#certifications">Certifications</a></li>
        <li><a href="#contact">Contact</a></li>
        <li><a href="#findme">Find Me</a></li>
      </ul>
    </nav>
  );
};

export default Navbar1;
